void be(Bytes&b,uint32_t n){for(int i=3;i>=0;i--)b.push_back((n>>(8*i))&255);}
uint32_t crc(std::span<const unsigned char> b){uint32_t c=~0u;for(auto v:b){c^=v;for(int k=0;k<8;k++)c=c&1?(c>>1)^0xedb88320:c>>1;}return ~c;}
void chunk(Bytes&out,const char *name,std::span<const unsigned char>b){be(out,b.size());size_t start=out.size();out.insert(out.end(),name,name+4);out.insert(out.end(),b.begin(),b.end());be(out,crc(std::span(out).subspan(start)));}
