std::vector<Id> selectedIds(const Document&d,std::span<const Id> ids){if(ids.empty()){std::vector<Id>out;for(auto&o:d.objects)if(o.visible){bool visible=true;for(Id p=o.parent;p;p=d.find(p)->parent)visible&=d.find(p)->visible;if(visible)out.push_back(o.id);}return out;}return {ids.begin(),ids.end()};}
