Bytes png(const Image &im){if(im.width<1||im.height<1||im.rgba.size()!=size_t(im.width)*im.height*4)throw std::runtime_error("Invalid RGBA image");Bytes out{137,80,78,71,13,10,26,10},header;be(header,im.width);be(header,im.height);header.insert(header.end(),{8,6,0,0,0});chunk(out,"IHDR",header);Bytes raw;raw.reserve((im.width*4+1)*im.height);for(int y=0;y<im.height;y++){raw.push_back(0);raw.insert(raw.end(),im.rgba.begin()+size_t(y)*im.width*4,im.rgba.begin()+size_t(y+1)*im.width*4);}Bytes z{0x78,0x01};uint32_t a=1,b=0;for(auto v:raw){a=(a+v)%65521;b=(b+a)%65521;}for(size_t p=0;p<raw.size();){size_t n=std::min<size_t>(65535,raw.size()-p);z.push_back(p+n==raw.size()?1:0);z.push_back(n&255);z.push_back(n>>8);z.push_back((~n)&255);z.push_back((~n)>>8&255);z.insert(z.end(),raw.begin()+p,raw.begin()+p+n);p+=n;}be(z,(b<<16)|a);chunk(out,"IDAT",z);chunk(out,"IEND",{});return out;}
